# study-2/app/different-contracts-app/app.R
library(shiny)
library(dplyr)

# -----------------------------
# Data loaders
# -----------------------------
load_data <- function() {
  p <- "data/df_bsc_longforapp.csv"
  if (!file.exists(p)) stop("Missing data/df_bsc_longforapp.csv in study-2/app/different-contracts-app/data/")
  read.csv(p, check.names = FALSE, stringsAsFactors = FALSE)
}

load_var_info <- function() {
  p <- "data/var_info.csv"
  if (!file.exists(p)) {
    return(data.frame(var=character(), label=character(), description=character(), stringsAsFactors = FALSE))
  }
  vi <- read.csv(p, check.names = FALSE, stringsAsFactors = FALSE)
  names(vi) <- tolower(names(vi))
  if (!"var" %in% names(vi)) vi$var <- character(0)
  if (!"label" %in% names(vi)) vi$label <- vi$var
  if (!"description" %in% names(vi)) vi$description <- ""
  vi$var <- trimws(vi$var); vi$label <- trimws(vi$label); vi$description <- trimws(vi$description)
  unique(vi[c("var","label","description")])
}

# -----------------------------
# Helpers
# -----------------------------
count_people <- function(df_sub) {
  if ("PID" %in% names(df_sub)) return(length(unique(df_sub$PID)))
  as.integer(nrow(df_sub))
}

pretty_label <- function(var, var_info) {
  lb <- var_info$label[match(var, var_info$var)]
  ifelse(is.na(lb) | !nzchar(lb), var, lb)
}

pretty_desc <- function(var, var_info) {
  ds <- var_info$description[match(var, var_info$var)]
  ifelse(is.na(ds) | !nzchar(ds), "", ds)
}

# Ideology variables
IDEO_VARS <- c("ideo_con","ideo_lib","ideo_lbrtn","ideo_demsoc","ideo_prog")

map_ideology_labels <- function(grp, levs_char) {
  if (!(grp %in% IDEO_VARS)) return(levs_char)
  lab0 <- switch(grp,
                 "ideo_con"   = "Not Conservatives",
                 "ideo_lib"   = "Not Liberals",
                 "ideo_lbrtn" = "Not Libertarians",
                 "ideo_demsoc"= "Not Democratic Socialists",
                 "ideo_prog"  = "Not Progressives"
  )
  lab1 <- switch(grp,
                 "ideo_con"   = "Conservatives",
                 "ideo_lib"   = "Liberals",
                 "ideo_lbrtn" = "Libertarians",
                 "ideo_demsoc"= "Democratic Socialists",
                 "ideo_prog"  = "Progressives"
  )
  out <- levs_char
  out[levs_char %in% c("0","0.0", "0L")] <- lab0
  out[levs_char %in% c("1","1.0", "1L")] <- lab1
  out
}

ideology_desc_override <- function(grp) {
  if (grp %in% IDEO_VARS) {
    "Anyone above the mid-point (4) on the ideology scale was counted as part of this ideological group."
  } else ""
}

summarize_values <- function(df_sub) {
  df_sub %>%
    group_by(value) %>%
    summarise(
      `Perceived Promise` = mean(weight, na.rm = TRUE),
      `Perceived Delivery` = mean(weighted_score, na.rm = TRUE),
      .groups = "drop"
    ) %>%
    mutate(Value = value) %>%
    select(Value, `Perceived Promise`, `Perceived Delivery`) %>%
    arrange(tolower(Value))
}

build_consolidated_table <- function(df, grp, categories) {
  vals_all <- sort(unique(df$value))
  out <- data.frame(Value = sort(vals_all), stringsAsFactors = FALSE)
  for (cat in categories) {
    sub <- df[df[[grp]] == cat, , drop = FALSE]
    if (nrow(sub) == 0) {
      out[[paste0(cat, " — Promise")]]  <- NA_real_
      out[[paste0(cat, " — Delivery")]] <- NA_real_
      next
    }
    s <- summarize_values(sub)
    names(s) <- c("Value", "Promise", "Delivery")
    out <- out %>%
      left_join(s, by = "Value") %>%
      rename(!!paste0(cat, " — Promise") := Promise,
             !!paste0(cat, " — Delivery") := Delivery)
  }
  out
}

# -----------------------------
# UI
# -----------------------------
ui <- fluidPage(
  titlePanel("Different Contracts for Different People"),
  tags$p(
    "In this app, you can explore how different sub-populations of the American public see the social contract. ",
    "Specifically, you can see what different groups believe the U.S.'s promise is on paper, and right next to it, ",
    "how they believe the U.S. government is doing in the delivery on that promise. We arrived at these numbers from ",
    "the way people assigned weights to what they believe the U.S. stands for on paper and from the weighted score ",
    "they gave to the U.S. government (across administrations) on each of the dimensions."
  ),
  sidebarLayout(
    sidebarPanel(
      helpText("Choose a characteristic to explore:"),
      selectInput("groupvar", "Break down by", choices = NULL),
      uiOutput("state_picker"),
      tags$hr(),
      helpText("Display modes:"),
      tags$p("• For age, race/ethnicity, region, and state: separate tables and plots for each category."),
      tags$p("• For all other variables: a consolidated table (superordinate headers) and paneled plots (one panel per category).")
    ),
    mainPanel(
      uiOutput("main_ui"),
      tags$hr(),
      h4("Description"),
      textOutput("chosen_desc")
    )
  )
)

# -----------------------------
# Server
# -----------------------------
server <- function(input, output, session) {
  df0 <- load_data()
  var_info <- load_var_info()
  names(df0) <- trimws(names(df0))

  allowed <- c("TIPI_extra","TIPI_agree","TIPI_consc","TIPI_neuro","TIPI_open",
               "ideo_con","ideo_lib","ideo_demsoc","ideo_lbrtn","ideo_prog",
               "party_id","edu","income","age","race_eth","gender","region","state")

  present_allowed <- intersect(allowed, names(df0))
  validate(need(length(present_allowed) > 0, "None of the requested grouping variables are present in the data."))

  labels <- var_info$label[match(present_allowed, var_info$var)]
  labels[is.na(labels) | !nzchar(labels)] <- present_allowed
  choices <- as.list(present_allowed); names(choices) <- labels
  updateSelectInput(session, "groupvar", choices = choices, selected = present_allowed[1])

  split_vars <- c("age","race_eth","region","state")

  output$state_picker <- renderUI({
    req(input$groupvar)
    if (identical(input$groupvar, "state")) {
      states <- sort(unique(na.omit(as.character(df0$state))))
      selectizeInput("states", "States to show", choices = states, multiple = TRUE,
                     options = list(plugins = list("remove_button"),
                                    placeholder = "Select one or more states"))
    } else NULL
  })

  output$chosen_desc <- renderText({
    req(input$groupvar)
    base <- pretty_desc(input$groupvar, var_info)
    over <- ideology_desc_override(input$groupvar)
    txt <- paste(c(base, over), collapse = if (nzchar(base) && nzchar(over)) " " else "")
    txt
  })

  output$main_ui <- renderUI({
    req(input$groupvar)
    grp <- input$groupvar

    if (grp %in% split_vars) {
      # ---- Split mode ----
      levs_raw <- if (grp == "state") input$states else sort(unique(na.omit(as.character(df0[[grp]]))))
      validate(need(length(levs_raw) >= 1, "Select at least one category to display."))

      panels <- lapply(seq_along(levs_raw), function(i) {
        lv <- levs_raw[i]
        df_sub <- df0[df0[[grp]] == lv, , drop = FALSE]
        n_people <- count_people(df_sub)
        sum_df <- summarize_values(df_sub)

        tbl_id  <- paste0("tbl_", i)
        plot_id <- paste0("plot_", i)

        local({
          df_sum <- sum_df
          output[[tbl_id]] <- renderTable({
            df_sum %>%
              mutate(
                `Perceived Promise` = sprintf("%.3f", `Perceived Promise`),
                `Perceived Delivery` = sprintf("%.3f", `Perceived Delivery`)
              )
          }, striped = TRUE, bordered = TRUE, hover = TRUE, spacing = "s")
        })

        local({
          df_sum <- sum_df
          output[[plot_id]] <- renderPlot({
            vals <- df_sum$Value
            prom <- df_sum$`Perceived Promise`
            del  <- df_sum$`Perceived Delivery`
            if (all(is.na(prom)) && all(is.na(del))) {
              plot.new(); title("No numeric data to plot"); return()
            }
            xlim <- range(0, prom, del, na.rm = TRUE)
            oldpar <- par(no.readonly = TRUE); on.exit(par(oldpar), add = TRUE)
            par(mfrow = c(2,1), mar = c(1,10,2,2), oma = c(4,0,0,0))
            barplot(prom, horiz = TRUE, names.arg = vals, las = 1, xlim = xlim,
                    col = "lightblue", border = "black", cex.names = 0.9) -> mp
            rect(xleft = 0, ybottom = mp - 0.4, xright = del, ytop = mp + 0.4,
                 col = adjustcolor("grey50", alpha.f = 0.5), border = "black")
            abline(v = axTicks(1), col = "grey70", lwd = 1)
            par(mar = c(0,0,0,0))
            plot.new()
            legend("center",
                   legend = c("Perceived Promise", "Perceived Delivery"),
                   fill   = c("lightblue", adjustcolor("grey50", 0.5)),
                   border = c("black", "black"),
                   bty = "n", horiz = TRUE, cex = 0.9, xpd = NA)
          })
        })

        wellPanel(
          tags$h4(paste0(pretty_label(grp, var_info), ": ", lv, " — N = ", n_people)),
          tableOutput(tbl_id),
          tags$div(style="height:12px;"),
          plotOutput(plot_id, height = "350px")
        )
      })
      tagList(panels)

    } else {
      # ---- Consolidated mode ----
      levs_raw <- sort(unique(na.omit(as.character(df0[[grp]]))))
      levs_disp <- if (grp %in% IDEO_VARS) map_ideology_labels(grp, levs_raw) else levs_raw
      cons_tbl <- build_consolidated_table(df0, grp, levs_raw)

      tbl_id <- "cons_table"
      output[[tbl_id]] <- renderUI({
        header_top <- tags$tr(
          tags$th("Value", style="border:1px solid #ddd; padding:6px; background:#f2f2f2; text-align:left;"),
          lapply(seq_along(levs_disp), function(j) {
            tags$th(colspan = 2,
                    style="border:1px solid #ddd; padding:6px; background:#f2f2f2; text-align:center;",
                    levs_disp[j])
          })
        )
        header_sub <- tags$tr(
          tags$th("", style="border:1px solid #ddd; padding:6px;"),
          lapply(rep(1, length(levs_disp)), function(i) {
            list(
              tags$th("Promise",  style="border:1px solid #ddd; padding:6px; text-align:center;"),
              tags$th("Delivery", style="border:1px solid #ddd; padding:6px; text-align:center;")
            )
          })
        )
        body_rows <- apply(cons_tbl, 1, function(row) {
          cells <- list(tags$td(row[[1]], style="border:1px solid #ddd; padding:6px; text-align:left;"))
          for (j in 2:length(row)) {
            val <- suppressWarnings(as.numeric(row[[j]]))
            if (is.na(val)) {
              cells <- c(cells, list(tags$td("", style="border:1px solid #ddd; padding:6px; text-align:center;")))
            } else {
              cells <- c(cells, list(tags$td(sprintf('%.3f', val), style="border:1px solid #ddd; padding:6px; text-align:center;")))
            }
          }
          do.call(tags$tr, cells)
        })
        tags$table(
          style="border-collapse:collapse; width:100%; table-layout:fixed; font-size:0.9em;",
          header_top, header_sub, body_rows
        )
      })

      plot_id <- "cons_plot"
      output[[plot_id]] <- renderPlot({
        per_cat <- lapply(seq_along(levs_raw), function(j) {
          lv_raw <- levs_raw[j]
          lv_lab <- levs_disp[j]
          sub <- df0[df0[[grp]] == lv_raw, , drop = FALSE]
          s   <- summarize_values(sub)
          list(vals = s$Value, prom = s$`Perceived Promise`, del = s$`Perceived Delivery`, lab = lv_lab)
        })
        xr <- range(0, unlist(lapply(per_cat, function(pc) c(pc$prom, pc$del))), na.rm = TRUE)
        n <- length(per_cat)
        cols <- if (n <= 2) 2 else if (n <= 4) 2 else if (n <= 6) 3 else 3
        rows <- ceiling(n / cols)
        oldpar <- par(no.readonly = TRUE); on.exit(par(oldpar), add = TRUE)
        lay_mat <- matrix(seq_len(rows * cols), nrow = rows, byrow = TRUE)
        lay_mat <- rbind(lay_mat, rep(max(lay_mat) + 1, ncol(lay_mat)))
        layout(lay_mat, heights = c(rep(1, rows), 0.30))
        par(mar = c(4.5, 9.5, 2, 1))
        for (i in seq_len(n)) {
          pc <- per_cat[[i]]
          mp <- barplot(pc$prom, horiz = TRUE, names.arg = pc$vals, las = 1, xlim = xr,
                        col = "lightblue", border = "black", cex.names = 0.85, main = pc$lab)
          rect(xleft = 0, ybottom = mp - 0.4, xright = pc$del, ytop = mp + 0.4,
               col = adjustcolor("grey50", alpha.f = 0.5), border = "black")
          abline(v = axTicks(1), col = "grey70", lwd = 1)
        }
        par(mar = c(0,0,0,0))
        plot.new()
        legend("center",
               legend = c("Perceived Promise", "Perceived Delivery"),
               fill   = c("lightblue", adjustcolor("grey50", 0.5)),
               border = c("black", "black"),
               bty = "n", horiz = TRUE, cex = 0.95, xpd = NA)
      })

      tagList(
        h4(pretty_label(input$groupvar, var_info)),
        uiOutput(tbl_id),
        tags$div(style="height:12px;"),
        plotOutput(plot_id, height = "480px")
      )
    }
  })
}

shinyApp(ui, server)

# study-2/app/lm-table-app/app.R
library(shiny)

`%||%` <- function(x, y) if (is.null(x)) y else x

# ---- Data loaders ----
load_data <- function() {
  p <- "data/df_bsc_elg.csv"
  if (!file.exists(p)) stop("Missing data/df_bsc_elg.csv in study-2/app/lm-table-app/data/")
  read.csv(p, check.names = FALSE, stringsAsFactors = FALSE)
}
load_var_info <- function() {
  p <- "data/var_info.csv"
  if (!file.exists(p)) return(data.frame(var=character(),label=character(),description=character()))
  vi <- read.csv(p, check.names = FALSE, stringsAsFactors = FALSE)
  names(vi) <- tolower(names(vi))
  if (!"var" %in% names(vi)) vi$var <- character(0)
  if (!"label" %in% names(vi)) vi$label <- vi$var
  if (!"description" %in% names(vi)) vi$description <- ""
  vi$var <- trimws(vi$var); vi$label <- trimws(vi$label); vi$description <- trimws(vi$description)
  unique(vi[c("var","label","description")])
}

# ---- Helpers ----
is_numlike <- function(x) {
  if (is.numeric(x)) return(TRUE)
  if (!is.character(x)) return(FALSE)
  ok <- suppressWarnings(!is.na(as.numeric(x)))
  mean(ok, na.rm = TRUE) > 0.9
}
coerce_for_lm <- function(df) {
  for (nm in names(df)) {
    if (is_numlike(df[[nm]])) {
      df[[nm]] <- suppressWarnings(as.numeric(df[[nm]]))
    } else if (!is.factor(df[[nm]])) {
      df[[nm]] <- factor(trimws(as.character(df[[nm]])))
    }
  }
  df
}

ui <- fluidPage(
  titlePanel("Broken Social Contract — Linear Model Table"),
  sidebarLayout(
    sidebarPanel(
      helpText("Build a linear model and view a tidy coefficient table."),
      selectInput("xvar", "Predictor (X)", choices = NULL),
      selectInput("yvar", "Outcome (Y)", choices = NULL),
      selectInput("zvar", "Moderator (Z) — optional", choices = NULL),
      selectizeInput(
        "controls", "Controls (0+)", choices = NULL, multiple = TRUE,
        options = list(
          plugins = list("remove_button"),
          persist = TRUE,
          openOnFocus = TRUE,
          closeAfterSelect = FALSE,
          placeholder = "Add any variables"
        )
      ),
      tags$hr(),
      helpText("Model:"),
      verbatimTextOutput("formtxt")
    ),
    mainPanel(
      tableOutput("lm_table"),
      plotOutput("viz", height = 420),
      tags$hr(),
      tags$h4("Selected variable info"),
      tableOutput("var_info_table"),
      tags$hr(),
      tags$h4("Notes"),
      tags$p("• Only variables listed in var_info.csv (and present in the data) are available."),
      tags$p("• If a moderator is chosen, the model includes main effects and the interaction (X × Z)."),
      tags$p("• Data were collected in May 2024. Therefore, voting variables indicate voting intentions, rather than voting behavior."),
      uiOutput("mod_note")
    )
  )
)

server <- function(input, output, session) {
  df0 <- load_data(); names(df0) <- trimws(names(df0))
  var_info <- load_var_info()

  listed <- unique(trimws(var_info$var))
  available_all <- intersect(names(df0), listed)
  validate(need(length(available_all) >= 2,
                "Need at least two variables that are listed in var_info.csv and present in the dataset."))

  bin_vars <- c("republican","democrat","independent",
                "vote_2024_trump","vote_2024_biden","vote_2024_rfkj","vote_2024_other",
                "white","man")

  lab_of <- function(v) {
    lb <- var_info$label[match(v, var_info$var)]
    ifelse(is.na(lb) | !nzchar(lb), v, lb)
  }
  get_desc <- function(v) {
    ds <- var_info$description[match(v, var_info$var)]
    ifelse(is.na(ds) | !nzchar(ds), "", ds)
  }

  labs <- lab_of(available_all)
  choices_all <- as.list(available_all); names(choices_all) <- labs

  updateSelectInput(session, "xvar", choices = choices_all, selected = available_all[1])
  updateSelectInput(session, "yvar", choices = choices_all, selected = available_all[min(2, length(available_all))])
  updateSelectInput(session, "zvar", choices = c("None" = "", choices_all), selected = "")

  prev_ctrl_pool <- reactiveVal(character(0))
  observe({
    cur_exclude <- unique(c(input$yvar, input$xvar, input$zvar))
    cur_exclude <- cur_exclude[nzchar(cur_exclude)]
    ctrl_pool <- setdiff(available_all, cur_exclude)

    if (identical(ctrl_pool, prev_ctrl_pool())) return(NULL)

    lab_ctrl <- lab_of(ctrl_pool)
    ctrl_choices <- as.list(ctrl_pool); names(ctrl_choices) <- lab_ctrl
    keep <- intersect(isolate(input$controls) %||% character(0), ctrl_pool)

    freezeReactiveValue(input, "controls")
    updateSelectizeInput(session, "controls",
                         choices = ctrl_choices,
                         selected = keep,
                         server = TRUE
    )
    prev_ctrl_pool(ctrl_pool)
  })

  term_label <- function(term) {
    if (term == "(Intercept)") return("Intercept")
    parts <- strsplit(term, ":", fixed = TRUE)[[1]]
    lbls  <- lab_of(parts)
    if (length(parts) > 1) paste(lbls, collapse = " × ") else lbls
  }

  model_spec <- reactive({
    req(input$yvar, input$xvar)
    y <- input$yvar; x <- input$xvar; z <- input$zvar; ctrls <- input$controls
    rhs <- if (nzchar(z)) paste(c(x, z, paste0(x, ":", z), ctrls), collapse = " + ")
    else paste(c(x, ctrls), collapse = " + ")
    as.formula(paste(y, "~", rhs))
  })

  output$formtxt <- renderText({
    paste(capture.output(model_spec()), collapse = "\n")
  })

  lm_fit <- reactive({
    d <- df0
    vars_needed <- all.vars(model_spec())
    d <- d[, intersect(vars_needed, names(d)), drop = FALSE]
    d <- coerce_for_lm(d)
    lm(model_spec(), data = d, na.action = na.omit)
  })

  output$lm_table <- renderTable({
    sm <- summary(lm_fit()); co <- sm$coefficients; rn <- rownames(co); rdf <- sm$df[2]
    data.frame(
      term     = vapply(rn, term_label, character(1)),
      beta     = sprintf("%.4f", unname(co[, "Estimate"])),
      t        = sprintf("%.3f", unname(co[, "t value"])),
      df       = as.integer(rdf),
      p_value  = ifelse(unname(co[, "Pr(>|t|)"]) < .001, "< .001",
                        sprintf("%.3f", unname(co[, "Pr(>|t|)"]))),
      stringsAsFactors = FALSE
    )
  }, striped = TRUE, bordered = TRUE, hover = TRUE, spacing = "m")

  output$viz <- renderPlot({
    fit <- lm_fit()
    d_fit <- model.frame(fit)
    x <- input$xvar; y <- input$yvar; z <- input$zvar

    lwd_line <- 2.6
    col_blue <- "blue"; col_red <- "red"; col_green <- "green"; col_gray <- "darkgray"
    pt_col <- rgb(0,0,0,0.12)

    op <- par(no.readonly = TRUE); on.exit(par(op), add = TRUE)
    par(xpd = NA); par(mar = par("mar") + c(2,0,0,0))

    typical_val <- function(v) {
      vv <- d_fit[[v]]
      if (is.numeric(vv)) mean(vv, na.rm = TRUE)
      else if (is.factor(vv)) factor(names(sort(table(vv), decreasing=TRUE))[1], levels=levels(vv))
      else names(sort(table(vv), decreasing=TRUE))[1]
    }
    rep_n <- function(val,n) if (is.factor(val)) factor(rep(as.character(val),n),levels=levels(val)) else rep(val,n)

    xv <- d_fit[[x]]; yv <- d_fit[[y]]
    if (!is.numeric(xv)) {
      x_fac <- factor(xv); x_num <- as.numeric(x_fac)
      plot(jitter(x_num,0.2), yv, pch=16, col=pt_col,
           xaxt="n", xlab=lab_of(x), ylab=lab_of(y), main="Mean outcome by X (X is non-numeric)")
      axis(1, at=seq_along(levels(x_fac)), labels=levels(x_fac))
      pts_mean <- tapply(yv, x_fac, mean, na.rm=TRUE)
      points(seq_along(pts_mean), pts_mean, pch=19, cex=1.2, col=col_blue)
      return()
    }

    x_seq <- seq(min(xv,na.rm=TRUE), max(xv,na.rm=TRUE), length.out=100); N <- length(x_seq)
    nd_row <- lapply(names(d_fit), typical_val); names(nd_row) <- names(d_fit)
    nd <- as.data.frame(nd_row, stringsAsFactors=FALSE)[rep(1,N),,drop=FALSE]
    for (nm in names(d_fit)) nd[[nm]] <- rep_n(nd[[nm]][1], N)
    nd[[x]] <- x_seq

    use_z <- nzchar(z)
    z_in_fit <- if (use_z) d_fit[[z]] else NULL
    z_is_numeric <- use_z && is.numeric(z_in_fit)
    z_is_binary <- use_z && (z %in% bin_vars)

    plot(xv, yv, pch=16, col=pt_col,
         xlab=lab_of(x), ylab=lab_of(y),
         main=if (use_z&&z_is_numeric) paste0("Simple slopes at ",lab_of(z)," = {−1 SD, mean, +1 SD}")
         else if (use_z&&z_is_binary) paste0("Effect of ",lab_of(x)," on ",lab_of(y)," by ",lab_of(z)," (0 vs 1)")
         else "Model-implied trend")

    if (use_z && z_is_binary) {
      is_factor_z <- is.factor(z_in_fit); levs <- if (is_factor_z) levels(z_in_fit) else NULL
      leg <- c(); leg_cols <- c(col_gray,col_blue)
      for (i in 1:2) {
        nd_i <- nd
        if (is_factor_z) {
          val <- if (all(c("0","1")%in%levs)) c("0","1")[i] else levs[i]
          nd_i[[z]] <- factor(rep(val,N), levels=levs)
          leg[i] <- paste(lab_of(z),"=",val)
        } else {
          val <- i-1
          nd_i[[z]] <- rep(val,N)
          leg[i] <- paste(lab_of(z),"=",val)
        }
        yhat <- predict(fit,newdata=nd_i)
        lines(x_seq,yhat,lwd=lwd_line,col=leg_cols[i])
      }
      legend("bottom", inset=-0.18, xpd=NA, horiz=TRUE,
             legend=leg, lty=1, lwd=lwd_line, col=leg_cols, bty="n")
      output$mod_note <- renderUI(HTML("&nbsp;"))

    } else if (use_z && z_is_numeric) {
      z_mean <- mean(z_in_fit,na.rm=TRUE); z_sd <- sd(z_in_fit,na.rm=TRUE)
      z_vals <- c(z_mean-z_sd, z_mean, z_mean+z_sd)
      leg <- c(paste(lab_of(z),"= -1 SD"),paste(lab_of(z),"= Mean"),paste(lab_of(z),"= +1 SD"))
      leg_cols <- c(col_red,col_blue,col_green)
      for (i in 1:3) {
        nd_i <- nd; nd_i[[z]] <- rep(z_vals[i],N)
        yhat <- predict(fit,newdata=nd_i)
        lines(x_seq,yhat,lwd=lwd_line,col=leg_cols[i])
      }
      legend("bottom", inset=-0.18, xpd=NA, horiz=TRUE,
             legend=leg, lty=1, lwd=lwd_line, col=leg_cols, bty="n")
      output$mod_note <- renderUI(HTML("&nbsp;"))
    } else {
      yhat <- predict(fit,newdata=nd)
      lines(x_seq,yhat,lwd=lwd_line,col=col_blue)
      output$mod_note <- renderUI(HTML("&nbsp;"))
    }
  })

  output$var_info_table <- renderTable({
    x <- input$xvar; y <- input$yvar; z <- input$zvar
    rows <- list(
      c(role="Predictor (X)", var=x, label=lab_of(x), description=get_desc(x)),
      c(role="Outcome (Y)", var=y, label=lab_of(y), description=get_desc(y))
    )
    if (nzchar(z)) rows <- c(rows,list(c(role="Moderator (Z)",var=z,label=lab_of(z),description=get_desc(z))))
    as.data.frame(do.call(rbind,rows), stringsAsFactors=FALSE)
  }, striped=TRUE, bordered=TRUE, hover=TRUE, spacing="s")
}

